  'tool2-pro2' => 'Ավելացնում է թվային ստորագրություններ ժամանակի դրոշմակնիքներով:',
  'tool2-pro3' => 'Վերահսկում է ինչպես կոդավորումը, այնպես էլ օգտագործողի թույլտվությունները:',
  'tool2-con1' => 'Ամբողջական գործառույթները պահանջում են վճարովի լիցենզիա:',
  'tool2-con2' => 'Անվտանգության որոշ տարբերակներ պահանջում են խորը ուսուցում:',
  'tool2-con3' => 'Պահանջվում է աշխատասեղանի տեղադրում, որը պահանջում է սարքի պահեստային տարածք:',
  'tool3-heading' => 'PDFEncrypt.net',
  'tool3-para' => 'PDFEncrypt.net-ը Windows-ի անվճար և բաց կոդով ծրագիր է, որը կոդավորում է PDF ֆայլերը: Այն թույլ է տալիս օգտվողներին ավելացնել գաղտնաբառ՝ առանց փաստաթղթեր վերբեռնելու սերվեր: Այն իդեալական է այն անհատների համար, ովքեր ցանկանում են պարզ անցանց պաշտպանություն առանց ծախսերի:',
  'tool3-pro1' => 'Անվճար, բաց կոդով և անցանց օգտագործում:',
  'tool3-pro2' => 'Խուսափում է առցանց ֆայլեր վերբեռնելուց:',
  'tool3-pro3' => 'Լավ է աշխատում ստանդարտ գաղտնագրման կարիքների համար:',
  'tool3-con1' => 'Սահմանափակ առաջադեմ անվտանգության գործիքներ:',
  'tool3-con2' => 'Միայն Windows-ի կիրառական միջավայր:',
  'tool3-con3' => 'Ոչ առցանց աջակցություն կամ թարմացումներ:',
  'tool4-heading' => 'iLovePDF',
  'tool4-para' => 'iLovePDF-ը պարզ առցանց ծրագիր է, որը գաղտնաբառեր է ավելացնում ձեր PDF ֆայլերին և գաղտնագրում դրանք ժամանակակից չափանիշներով: Դուք կարող եք ընտրել՝ գաղտնաբառը միայն բացելու համար է, թե նաև խմբագրման սահմանափակումների համար: Այն անվճար է և աշխատում է անմիջապես բրաուզերում:',
  'tool4-pro1' => 'Անվճար և հեշտ օգտագործվող առցանց գործիք:',
  'tool4-pro2' => 'Աջակցում է պաշտպանության մի քանի տեսակների:',
  'tool4-pro3' => 'Աշխատում է զննարկիչով ցանկացած սարքի վրա:',
  'tool4-con1' => 'Առցանց ծառայության համար անհրաժեշտ է ինտերնետ հասանելիություն:',
  'tool4-con2' => 'Ֆայլի չափի սահմանափակումները կարող են կիրառվել:',
  'tool4-con3' => 'Ոչ մի լրացուցիչ գործառույթ, ինչպիսին ստորագրություններն են:',
  'tool5-heading' => 'Smallpdf',
  'tool5-para' => 'Smallpdf-ը մասնագիտացած է հեշտ առցանց PDF առաջադրանքների մեջ, ներառյալ գաղտնաբառի պաշտպանությունը: Կայքը գաղտնագրում է ֆայլերը՝ օգտագործելով AES կոդավորումը և թույլ է տալիս արագ կիսվել անվտանգ ֆայլերով: Սա լավ ընտրություն է արագ պաշտպանության համար՝ առանց ծրագրեր տեղադրելու:',
  'tool5-pro1' => 'Արագ և օգտագործելի շատ սարքերում:',
  'tool5-pro2' => 'Տեղադրման կարիք չկա:',
  'tool5-pro3' => 'Ուժեղ գաղտնագրում մշակման ընթացքում:',
  'tool5-con1' => 'Սահմանափակ անցանց օգտագործում:',
  'tool5-con2' => 'Առավելագույն չափի սահմանափակումներ առանց բաժանորդագրության:',
  'tool5-con3' => 'Չկան առաջադեմ փաստաթղթերի գործիքներ:',
  'comparison-intro' => 'Ահա վերը նշված գործիքների համառոտ համեմատությունը:',
  'table-col1' => 'Գործիք',
  'table-col2' => 'Անվտանգության ուժ',
  'table-col3' => 'Առցանց/Օֆլայն',
  'table-col4' => 'Ընդլայնված հատկություններ',
  'table-row1-col1' => 'Adobe Acrobat',
  'table-row1-col2' => 'Բարձր',
  'table-row1-col3' => 'Առցանց + Անցանց',
  'table-row1-col4' => 'Այո՛',
  'table-row2-col1' => 'Foxit PDF խմբագիր',
  'table-row2-col2' => 'Բարձր',
  'table-row2-col3' => 'Անցանց',
  'table-row2-col4' => 'Այո՛',
  'table-row3-col1' => 'PDFEncrypt.net',
  'table-row3-col2' => 'Միջին',
  'table-row3-col3' => 'Անցանց',
  'table-row3-col4' => 'Ոչ',
  'table-row4-col1' => 'iLovePDF',
  'table-row4-col2' => 'Միջին',
  'table-row4-col3' => 'Առցանց',
  'table-row4-col4' => 'Հիմնական',
  'table-row5-col1' => 'Smallpdf',
  'table-row5-col2' => 'Միջին',
  'table-row5-col3' => 'Առցանց',
  'table-row5-col4' => 'Հիմնական',
  'comparison-note' => 'Եթե ​​ձեր փաստաթղթերը պահանջում են բարձր վերահսկողություն և իրավական համապատասխանություն, Adobe Acrobat կամ Foxit PDF Editor-ը ամենաուժեղ ընտրությունն է: Եթե ​​Ձեզ անհրաժեշտ է պարզ պաշտպանություն փոքր կարգավորումներով, iLovePDF-ը կամ Smallpdf-ը կարող են օգնել ձեզ արագ պաշտպանել ֆայլերը: PDFEncrypt.net-ը լավ է աշխատում, երբ դուք ցանկանում եք պաշտպանել անցանց ռեժիմն անվճար:',
  'best-practices-heading' => 'PDF անվտանգության լավագույն փորձը',
  'best-practices-intro' => 'Զգայուն PDF ֆայլի պաշտպանությունը կարևոր խնդիր է: Ահա մի քանի ամենակարևոր անվտանգության պրակտիկաները, որոնք պետք է հաշվի առնել:',
  'practice1-heading' => 'Օգտագործեք ուժեղ գաղտնաբառեր',
  'practice1-para' => 'Ուժեղ գաղտնաբառերը պաշտպանում են PDF ֆայլերը անցանկալի մուտքից և անհոգ տարածումից: Գաղտնաբառերը պետք է ներառեն տառեր, թվեր և նշաններ՝ ավելի բարձր դիմադրության համար: Թիմերը պետք է խուսափեն բազմաթիվ փաստաթղթերում կամ հարթակներում գաղտնաբառերի վերօգտագործումից:',
  'practice2-heading' => 'Կիրառել ժամանակակից կոդավորումը',
  'practice2-para' => 'Գաղտնագրման ժամանակակից ստանդարտները պաշտպանում են բովանդակությունը պահպանման և ֆայլերի փոխանցման ժամանակ: AES կոդավորումն ապահովում է հուսալի անվտանգություն բիզնեսի և անձնական փաստաթղթերի համար: Օգտագործողները պետք է ստուգեն գործիքի կարգավորումները և հաստատեն, որ գաղտնագրումը միշտ միացված է:',
  'practice3-heading' => 'Սահմանափակել օգտվողի թույլտվությունները',
  'practice3-para' => 'Թույլտվությունների կառավարումը սահմանափակում է պաշտպանված PDF ֆայլերի ներսում խմբագրումը, տպումը և պատճենումը: Ստեղծողները պետք է թույլատրեն միայն պահանջվող գործողություններ յուրաքանչյուր ընդհանուր փաստաթղթի համար: Սահմանափակ թույլտվությունները նվազեցնում են սխալները և կանխում տվյալների չարաշահման ռիսկերը:',
  'practice4-heading' => 'Վերահսկել ֆայլերի փոխանակումը',
  'practice4-para' => 'Համօգտագործման անվտանգ մեթոդները նվազեցնում են բացահայտումը էլփոստի կամ ամպային փոխանցումների ժամանակ: Ժամկետի ժամկետներով անձնական հղումներն ավելացնում են անվտանգության ևս մեկ շերտ: Վստահելի հարթակներն օգնում են հետևել մուտքին և նվազեցնել չարտոնված բաշխումը:',
  'practice5-heading' => 'Պահպանեք կանոնավոր ակնարկներ',
  'practice5-para' => 'Կանոնավոր վերանայումները օգնում են հաստատել, որ անվտանգության կարգավորումները ժամանակի ընթացքում մնում են արդյունավետ: Թիմերը պետք է թարմացնեն գաղտնաբառերը անձնակազմի փոփոխություններից կամ նախագծի ավարտից հետո: Պարբերական ստուգումները աջակցում են համապատասխանությանը և շարունակաբար պաշտպանում են զգայուն տեղեկատվությունը:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-para1' => 'PDF ֆայլերը հաճախ պահում են մասնավոր տեղեկատվություն բազմաթիվ ոլորտների մասնագետների, ուսանողների և մանկավարժների համար: Անվտանգության ուժեղ հսկողությունն օգնում է օգտատերերին կառավարել մուտքը և նվազեցնել թվային աշխատանքի ռիսկերը: Փաստաթղթերի հստակ կանոնները բարելավում են վստահությունը և աջակցում են տեղեկատվության անվտանգ փոխանակմանը:',
  'conclusion-para2-1' => 'PDF անվտանգությունը օգտագործում է գաղտնաբառեր, գաղտնագրում և թույլտվություններ՝ արդյունավետորեն չարաշահումը արգելափակելու համար: Շատ օգտվողներ',
  'conclusion-para2-2' => 'գաղտնաբառով պաշտպանված PDF ֆայլեր',
  'conclusion-para2-3' => 'դիտելու, խմբագրելու և տպելու իրավունքները վերահսկելու համար: Կոդավորումը պահում է բովանդակությունը անընթեռնելի, մինչև հաստատված օգտվողները մուտքագրեն ճիշտ հավատարմագրերը:',
  'conclusion-para3' => 'Առցանց գործիքները պարզեցնում են PDF-ի պաշտպանությունը գաղտնաբառի տեղադրման միջոցով՝ վերբեռնման և անվտանգ ներբեռնման քայլերի համար: Հանրաճանաչ գործիքներն առաջարկում են տարբեր գործառույթներ, որոնք համապատասխանում են բիզնեսի, իրավական կամ անձնական կարիքներին: Հզոր գաղտնաբառի կոդավորումը և կանոնավոր վերանայումները ապահովում են փաստաթղթերի երկարաժամկետ անվտանգությունը:',
  'faqs-heading' => 'ՀՏՀ-ներ',
  'faq1-question' => 'Կարո՞ղ եմ PDF ֆայլերը անվճար պաշտպանել:',
  'faq1-answer' => 'Շատ առցանց գործիքներ առաջարկում են անվճար PDF պաշտպանություն՝ ապահով կերպով ներառված գաղտնաբառի հիմնական հատկանիշներով: Անվճար պլանները հաճախ սահմանափակում են ֆայլի չափի օգտագործման հաճախականությունը կամ առաջադեմ անվտանգության վերահսկումը: Օգտագործողները պետք է վերանայեն սահմանաչափերը՝ նախքան զգայուն փաստաթղթերի համար անվճար լուծում ընտրելը:',
  'faq2-question' => 'Արդյո՞ք գաղտնագրումն ուժեղ պաշտպանիչ հատկանիշ է PDF-ների համար:',
  'faq2-answer' => 'Ժամանակակից PDF գաղտնագրումը օգտագործում է ուժեղ ստանդարտներ, որոնք պաշտպանում են տվյալները չարտոնված մուտքից: AES-ի վրա հիմնված գաղտնագրումը դիմակայում է սովորական հարձակումներին և աջակցում է ընթացիկ մասնագիտական ​​անվտանգության պահանջներին: Անվտանգության հզորությունը կախված է գաղտնաբառի որակից և այսօր կոդավորման ճիշտ կարգավորումներից:',
  'faq3-question' => 'Կարո՞ղ եմ սահմանափակել խմբագրումը PDF ֆայլերում:',
  'faq3-answer' => 'PDF պաշտպանության գործիքները ստեղծողներին թույլ են տալիս ապահով կերպով սահմանափակել խմբագրման, տպագրության և պատճենման գործողությունները: Թույլտվությունների կարգավորումները օգնում են պահպանել փաստաթղթի ճշգրտությունը և կանխել բովանդակության անցանկալի փոփոխությունները: Խմբագիրները մուտք են ստանում միայն այն դեպքում, երբ սեփականատերերը միտումնավոր և հստակորեն տրամադրում են հատուկ իրավունքներ:',
  'faq4-question' => 'Արդյո՞ք պաշտպանությունը ազդում է PDF ֆայլի չափի վրա:',
  'faq4-answer' => 'PDF պաշտպանությունը սովորաբար առաջացնում է փոքր ֆայլի չափի փոփոխություններ գաղտնագրման հավելվածից հետո: Գաղտնաբառի անվտանգությունը ավելացնում է մետատվյալներ և գաղտնագրման տվյալներ, ինչը փոքր-ինչ մեծացնում է պահեստավորման կարիքները: Օգտատերերի մեծամասնությունը երբեք չի նկատում չափերի տարբերություններ առցանց գործողությունների փոխանակման կամ ներբեռնման ժամանակ:',
  'faq5-question' => 'Հնարավո՞ր է գաղտնաբառերը հեռացնել PDF ֆայլերից:',
  'faq5-answer' => 'Գաղտնաբառերը կարող են հեռացվել միայն այն դեպքում, երբ սեփականատերերը հիշում են իրենց հավատարմագրերը կամ օգտագործում են լիազորված գործիքներ: Անհայտ գաղտնաբառերը արգելափակում են հեռացման փորձերը և պաշտպանում փաստաթղթերը հարկադիր մուտքից: Օգտատերերը պետք է ապահով պահեն գաղտնաբառերը՝ փաստաթղթերի կողպման մշտական ​​խնդիրներից խուսափելու համար:',
);
